import { z } from 'zod';
import { CursorQuerySchema, pageSchema } from '../../lib/pagination.ts';

export const ProjectStatusSchema = z.enum(['active', 'archived']);

export const ProjectSchema = z.object({
  id: z.uuid(),
  name: z.string().min(1).max(100),
  description: z.string().max(500).optional(),
  status: ProjectStatusSchema,
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
});
export type Project = z.infer<typeof ProjectSchema>;

export const ProjectParamsSchema = z.object({ projectId: z.uuid() });

export const CreateProjectSchema = z.strictObject({
  name: z.string().min(1).max(100),
  description: z.string().max(500).optional(),
  status: ProjectStatusSchema.default('active'),
});
export type CreateProject = z.infer<typeof CreateProjectSchema>;

export const UpdateProjectSchema = z
  .strictObject({
    name: z.string().min(1).max(100).optional(),
    description: z.string().max(500).optional(),
    status: ProjectStatusSchema.optional(),
  })
  .refine((patch) => Object.keys(patch).length > 0, { message: 'at least one field is required' });
export type UpdateProject = z.infer<typeof UpdateProjectSchema>;

export const ListProjectsQuerySchema = CursorQuerySchema.extend({
  status: ProjectStatusSchema.optional(),
});
export type ListProjectsQuery = z.infer<typeof ListProjectsQuerySchema>;

export const ProjectPageSchema = pageSchema(ProjectSchema);
export type ProjectPage = z.infer<typeof ProjectPageSchema>;

import { randomUUID } from 'node:crypto';
import { paginate } from '../../lib/pagination.ts';
import type { CreateProject, ListProjectsQuery, Project, ProjectPage, UpdateProject } from './schema.ts';

/** In-memory project store, ordered by creation time (ties broken by id). */
const projects = new Map<string, Project>();

const sortKey = (project: Project): string => `${project.createdAt}|${project.id}`;

export function listProjects(query: ListProjectsQuery): ProjectPage {
  const filteredProjects = query.status === undefined
    ? [...projects.values()]
    : [...projects.values()].filter((project) => project.status === query.status);

  return paginate(filteredProjects, query, sortKey);
}

export function getProject(id: string): Project | undefined {
  return projects.get(id);
}

export function createProject(input: CreateProject): Project {
  const now = new Date().toISOString();
  const project: Project = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
  projects.set(project.id, project);
  return project;
}

export function updateProject(id: string, patch: UpdateProject): Project | undefined {
  const current = projects.get(id);
  if (current === undefined) return undefined;
  const updated: Project = { ...current, ...patch, updatedAt: new Date().toISOString() };
  projects.set(id, updated);
  return updated;
}

export function deleteProject(id: string): boolean {
  return projects.delete(id);
}

import { Router } from 'express';
import { idempotency } from '../../lib/idempotency.ts';
import { notFound } from '../../lib/problem.ts';
import {
  CreateProjectSchema,
  ListProjectsQuerySchema,
  ProjectPageSchema,
  ProjectParamsSchema,
  ProjectSchema,
  UpdateProjectSchema,
} from './schema.ts';
import { createProject, deleteProject, getProject, listProjects, updateProject } from './store.ts';

export const projectsRouter = Router();

projectsRouter.get('/v1/projects', (req, res) => {
  const query = ListProjectsQuerySchema.parse(req.query);
  res.json(ProjectPageSchema.parse(listProjects(query)));
});

projectsRouter.post('/v1/projects', idempotency(), (req, res) => {
  const body = CreateProjectSchema.parse(req.body);
  const project = createProject(body);
  res.status(201).location(`/v1/projects/${project.id}`).json(ProjectSchema.parse(project));
});

projectsRouter.get('/v1/projects/:projectId', (req, res) => {
  const { projectId } = ProjectParamsSchema.parse(req.params);
  const project = getProject(projectId);
  if (project === undefined) throw notFound(`project ${projectId} not found`);
  res.json(ProjectSchema.parse(project));
});

projectsRouter.patch('/v1/projects/:projectId', idempotency(), (req, res) => {
  const { projectId } = ProjectParamsSchema.parse(req.params);
  const patch = UpdateProjectSchema.parse(req.body);
  const project = updateProject(projectId, patch);
  if (project === undefined) throw notFound(`project ${projectId} not found`);
  res.json(ProjectSchema.parse(project));
});

projectsRouter.delete('/v1/projects/:projectId', (req, res) => {
  const { projectId } = ProjectParamsSchema.parse(req.params);
  const deleted = deleteProject(projectId);
  if (!deleted) throw notFound(`project ${projectId} not found`);
  res.status(204).send();
});

