export function listProjects(query: ListProjectsQuery): ProjectPage {
  const projects = [...store.values()].sort((a, b) => a.id.localeCompare(b.id));
  const filtered = query.status === undefined ? projects : projects.filter((project) => project.status === query.status);

  if (query.cursor === undefined) {
    return paginate(filtered, query, (project) => project.id);
  }

  const after = decodeCursor(query.cursor);
  const filteredIds = new Set(filtered.map((project) => project.id));
  if (!filteredIds.has(after)) {
    throw unprocessable('cursor does not match the current filter');
  }

  return paginate(filtered, query, (project) => project.id);
}

