 3| import type { CreateProject, ListProjectsQuery, Project, ProjectPage, UpdateProject } from './schema.ts';
 4| 
 5| /** In-memory project store, ordered by creation time (ties broken by id). */
 6| const projects = new Map<string, Project>();
 7| 
 8| const sortKey = (project: Project): string => `${project.createdAt}|${project.id}`;
 9| 
10| export function listProjects(query: ListProjectsQuery): ProjectPage {
11|   const filteredProjects = query.status === undefined
12|     ? [...projects.values()]
13|     : [...projects.values()].filter((project) => project.status === query.status);
14| 
15|   return paginate(filteredProjects, query, sortKey);
16| }
17| 
18| export function getProject(id: string): Project | undefined {
19|   return projects.get(id);
20| }
21| 
22| export function createProject(input: CreateProject): Project {
23|   const now = new Date().toISOString();
24|   const project: Project = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
25|   projects.set(project.id, project);
26|   return project;
27| }
28| 
29| export function updateProject(id: string, patch: UpdateProject): Project | undefined {
30|   const current = projects.get(id);
31|   if (current === undefined) return undefined;
32|   const updated: Project = { ...current, ...patch, updatedAt: new Date().toISOString() };
33|   projects.set(id, updated);
34|   return updated;
35| }
